"""Thematic Japanese layout and in-world Russian prose. Does not change gameplay."""
from pathlib import Path
import json,re,shutil
from rebalance_1893_layout_population import layout

R=Path(__file__).resolve().parents[1]
B=R/'tools/backups/japan_presentation_20261013'

def save(p,s):
    b=B/p.relative_to(R)
    if not b.exists():
        b.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,b)
    raw=p.read_bytes()
    p.write_text(s,encoding='utf-8-sig' if p.suffix=='.yml' or raw.startswith(b'\xef\xbb\xbf') else 'utf-8',newline='\r\n' if b'\r\n' in raw else '\n')

